export const ba_fused_super_bench = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> inverse_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

{{> field8_funcs }}

// Fused super-kernel for the bin-packed pair-tree MSM bucket-accumulate.
//
// Combines marshal + disjoint + scatter into one kernel. Each thread t
// handles one pair_block of S pairs (a "pair_block" = the unit of fused
// affine-add work the level loop batches through a shared inversion):
//   1. Read 2*S source indices from pair_block_plan (idx_l, idx_r per slot).
//   2. Read S destination indices from scatter_plan.
//   3. Load S pair-x values from active_sums_old, compute S dx values
//      and forward prefix product.
//   4. Single field inversion on the prefix product.
//   5. Inverse pass: per slot k from S-1 down to 0, derive
//      inv_dx[k] = 1/dx_k from the running inverse and write it back to
//      pref_scratch. The running inverse is loop-carried only here.
//   6. Backward peel: per slot k, read inv_dx[k]:
//        - load .x and .y for both operands
//        - lean affine add -> R_x, R_y
//        - write directly to active_sums_new at scatter_plan[t*S + k]
//
// Field elements are 8x u32 throughout (Lever 2); see field8_funcs.
//
// PARAMS:
//   params.x = total_pair_blocks  (active threads, one per pair_block)
//   params.y = M_old              (active_sums_old vec4-stride length)
//   params.z = M_new              (active_sums_new vec4-stride length)
//
// Layout (both active_sums buffers): 2 planes (P.x, P.y), PG=2 vec4 per
// element. plane_p flat vec4 base = p * PG * M, element e at offset
// PG * e.

const S: u32 = {{ s }}u;
const PG: u32 = 2u;

@group(0) @binding(0) var<storage, read>       pair_block_plan:      array<u32>;
@group(0) @binding(1) var<storage, read>       scatter_plan:    array<u32>;
{{#l0_index_mode}}
// Lever B: at level 0 active_sums_old is a flat (point index | sign<<31)
// array; the operand points are gathered from the pool (point_x/point_y).
@group(0) @binding(2) var<storage, read>       active_sums_old: array<u32>;
{{/l0_index_mode}}
{{^l0_index_mode}}
@group(0) @binding(2) var<storage, read>       active_sums_old: array<vec4<u32>>;
{{/l0_index_mode}}
@group(0) @binding(3) var<storage, read_write> active_sums_new: array<vec4<u32>>;
@group(0) @binding(4) var<uniform>             params:          vec4<u32>;
@group(0) @binding(5) var<storage, read_write> pref_scratch:    array<vec4<u32>>;
{{#l0_index_mode}}
@group(0) @binding(6) var<storage, read>       point_x:         array<vec4<u32>>;
@group(0) @binding(7) var<storage, read>       point_y:         array<vec4<u32>>;
{{/l0_index_mode}}

{{#l0_index_mode}}
const L0_SIGN_BIT: u32 = 0x80000000u;
const L0_IDX_MASK: u32 = 0x7fffffffu;

// Level-0 operand load: active_sums_old[idx] is (point index | sign<<31);
// gather the coordinate from the pool. \`M\` is unused here.
fn load_active_x(idx: u32, M: u32) -> array<u32, 8> {
    let pt = active_sums_old[idx] & L0_IDX_MASK;
    let q0 = point_x[2u * pt];
    let q1 = point_x[2u * pt + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

fn load_active_y(idx: u32, M: u32) -> array<u32, 8> {
    let packed = active_sums_old[idx];
    let pt = packed & L0_IDX_MASK;
    let q0 = point_y[2u * pt];
    let q1 = point_y[2u * pt + 1u];
    let y: array<u32, 8> = array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
    if ((packed & L0_SIGN_BIT) == 0u) {
        return y;
    }
    // Lever D: negate y on the fly (-y = 0 - y mod p) — the level-0 point
    // pool carries no precomputed -y plane.
    let zero: array<u32, 8> = array<u32, 8>(0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
    return fr_sub_f8(zero, y);
}
{{/l0_index_mode}}
{{^l0_index_mode}}
fn load_active_x(idx: u32, M: u32) -> array<u32, 8> {
    let base = 0u * PG * M + PG * idx;
    let q0 = active_sums_old[base + 0u];
    let q1 = active_sums_old[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

fn load_active_y(idx: u32, M: u32) -> array<u32, 8> {
    let base = 1u * PG * M + PG * idx;
    let q0 = active_sums_old[base + 0u];
    let q1 = active_sums_old[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
{{/l0_index_mode}}

fn store_active_new(plane: u32, idx: u32, M: u32, val: array<u32, 8>) {
    let base = plane * PG * M + PG * idx;
    active_sums_new[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    active_sums_new[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

// pref_scratch holds the forward prefix products (then the per-slot
// inverses), 8x u32 = two vec4 per entry. Thread-major — global slot =
// t*S + k — so each thread's S entries are contiguous and stay
// cache-resident across the forward/backward gap.
fn store_pref(slot: u32, val: array<u32, 8>) {
    let base = 2u * slot;
    pref_scratch[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    pref_scratch[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn load_pref(slot: u32) -> array<u32, 8> {
    let base = 2u * slot;
    let q0 = pref_scratch[base + 0u];
    let q1 = pref_scratch[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let T = params.x;
    let M_old = params.y;
    let M_new = params.z;
    let t = gid.x{{#tiled}} + params.w{{/tiled}};
    if (t >= T) { return; }

    // pref_scratch index. Lever A (tiled) sizes pref_scratch to a single
    // tile of T_TILE threads, so it is indexed by the tile-local thread id
    // (gid.x); params.w carries the tile's global base. Untiled callers
    // pass params.w = 0 and pref_scratch spans all T threads.
{{#tiled}}
    let pref_base = gid.x * S;
{{/tiled}}
{{^tiled}}
    let pref_base = t * S;
{{/tiled}}

    let block_base = 2u * S * t;

    // Forward: compute S dx values and accumulate the prefix product.
    var acc: array<u32, 8> = get_r_f8();
    for (var k: u32 = 0u; k < S; k = k + 1u) {
        let idx_l = pair_block_plan[block_base + 2u * k + 0u];
        let idx_r = pair_block_plan[block_base + 2u * k + 1u];
        let p_lx: array<u32, 8> = load_active_x(idx_l, M_old);
        let p_rx: array<u32, 8> = load_active_x(idx_r, M_old);
        let dx: array<u32, 8> = fr_sub_f8(p_rx, p_lx);
        if (k == 0u) {
            acc = dx;
        } else {
            acc = montgomery_product_f8(acc, dx);
        }
        store_pref(pref_base + k, acc);
    }

    // Single inversion per pair_block. The safegcd inverse is 20x13-limb; the
    // accumulate is 8x u32, so expand on the way in and contract the
    // result — one conversion pair per pair_block.
    var acc20: BigInt = unpack256_to_limbs(acc);
    var inv20: BigInt = {{ inv_fn }}(acc20);
    var inv: array<u32, 8> = pack_limbs_to_256(&inv20);

    // Inverse pass: walk k descending, derive inv_dx[k] = 1/dx_k from the
    // running inverse + the stored forward prefix products, and write it
    // back into pref_scratch slot k. The running \`inv\` is loop-carried
    // only in this multiply-only loop, so it is NOT live across the
    // affine-add peel below. store_pref(k) is safe: a later (smaller-k)
    // iteration only reads slots < k, an earlier one only wrote slots > k.
    for (var jj: u32 = 0u; jj < S; jj = jj + 1u) {
        let k = S - 1u - jj;
        var inv_dx: array<u32, 8>;
        if (k == 0u) {
            inv_dx = inv;
        } else {
            let pp: array<u32, 8> = load_pref(pref_base + (k - 1u));
            inv_dx = montgomery_product_f8(inv, pp);
            // Advance the running inverse by dx_k for the next iteration;
            // dx_k is recomputed from the slot's x-coordinates.
            let idx_l = pair_block_plan[block_base + 2u * k + 0u];
            let idx_r = pair_block_plan[block_base + 2u * k + 1u];
            let p_lx: array<u32, 8> = load_active_x(idx_l, M_old);
            let p_rx: array<u32, 8> = load_active_x(idx_r, M_old);
            let dx_back: array<u32, 8> = fr_sub_f8(p_rx, p_lx);
            inv = montgomery_product_f8(inv, dx_back);
        }
        store_pref(pref_base + k, inv_dx);
    }

    // Backward peel: emit S pair sums, scatter to active_sums_new. Reads
    // the per-slot inverse inv_dx[k] from pref_scratch — no running
    // inverse is live across the affine add. Each coordinate is loaded
    // just before first use to minimise the simultaneously-live set.
    for (var jj: u32 = 0u; jj < S; jj = jj + 1u) {
        let k = S - 1u - jj;
        let idx_l = pair_block_plan[block_base + 2u * k + 0u];
        let idx_r = pair_block_plan[block_base + 2u * k + 1u];

        let inv_dx: array<u32, 8> = load_pref(pref_base + k);

        // lambda = (p_ry - p_ly) / dx_k.
        let p_ly: array<u32, 8> = load_active_y(idx_l, M_old);
        let p_ry: array<u32, 8> = load_active_y(idx_r, M_old);
        var lambda: array<u32, 8> = fr_sub_f8(p_ry, p_ly);
        lambda = montgomery_product_f8(lambda, inv_dx);

        // r_x = lambda^2 - p_lx - p_rx.
        let p_lx: array<u32, 8> = load_active_x(idx_l, M_old);
        let p_rx: array<u32, 8> = load_active_x(idx_r, M_old);
        var r_x: array<u32, 8> = montgomery_product_f8(lambda, lambda);
        let x_sum: array<u32, 8> = fr_add_f8(p_lx, p_rx);
        r_x = fr_sub_f8(r_x, x_sum);

        // r_y = lambda * (p_lx - r_x) - p_ly.
        var r_y: array<u32, 8> = fr_sub_f8(p_lx, r_x);
        r_y = montgomery_product_f8(lambda, r_y);
        r_y = fr_sub_f8(r_y, p_ly);

        let dst_idx = scatter_plan[t * S + k];
        store_active_new(0u, dst_idx, M_new, r_x);
        store_active_new(1u, dst_idx, M_new, r_y);
    }

    {{{ recompile }}}
}
`;

export const ba_planner_classify = `// Bucket-accumulate planner stage 1.1: 3-way classify.
//
// Partitions B_TOTAL buckets by count:
//   count == 0  → skip
//   count == 1  → size1_bucket_list  (consumed by ba_size1)
//   count >= 2  → dense_bucket_list + dense_count_list  (consumed by radix sort)
//
// Atomic counters in planner_meta[0] (num_size1) and planner_meta[1]
// (num_dense) track list lengths.

const B_TOTAL: u32 = {{ b_total }}u;
const BW:      u32 = {{ bw }}u;
const STRIDE:  u32 = {{ stride }}u;

@group(0) @binding(0) var<storage, read>       counts:             array<u32>;
@group(0) @binding(1) var<storage, read>       offsets:            array<u32>;
@group(0) @binding(2) var<storage, read_write> size1_bucket_list:  array<u32>;
@group(0) @binding(3) var<storage, read_write> dense_bucket_list:  array<u32>;
@group(0) @binding(4) var<storage, read_write> dense_count_list:   array<u32>;
@group(0) @binding(5) var<storage, read_write> planner_meta:       array<atomic<u32>>;
@group(0) @binding(6) var<uniform>             params:             vec4<u32>;

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let b = gid.x;
    if (b >= B_TOTAL) { return; }

    let n = counts[b];
    if (n == 0u) { return; }

    // Drop buckets whose magnitude is outside the reduce-valid range
    // [1, STRIDE]. Magnitude 0 is the zero-digit (no contribution after
    // weighting); magnitude > STRIDE is BW-padding (booth never produces
    // it, but guard defensively). Hoisting the filter here means walker
    // output kernels never need to check magnitude per-store.
    let magnitude = b % BW;
    if (magnitude == 0u || magnitude > STRIDE) { return; }

    if (n == 1u) {
        let slot = atomicAdd(&planner_meta[0], 1u);
        size1_bucket_list[2u * slot + 0u] = b;
        size1_bucket_list[2u * slot + 1u] = offsets[b];
    } else {
        let slot = atomicAdd(&planner_meta[1], 1u);
        dense_bucket_list[slot] = b;
        dense_count_list[slot] = n;
    }

    {{{ recompile }}}
}
`;

export const ba_planner_cumsum = `// Bucket-accumulate planner stage 1.3: prefix sum of (count - 1).
//
// Builds cumulative_adds[i] = exclusive prefix sum of
// (sorted_count_list[i] - 1) over i in [0, num_dense). The final
// inclusive sum = total_adds is written to planner_meta[2].
//
// Also computes num_workgroups and writes indirect dispatch args for
// ba_stream_accum at planner_meta[12..14].
//
// Uses a 3-phase chunked scan (same as transpose_parallel_scan):
//   A — each thread sums its chunk → wg_sums[tid]
//   B — Hillis-Steele inclusive scan on wg_sums
//   C — re-read chunk and write per-element exclusive prefix

// TPB = this cumsum kernel's own scan workgroup size. By convention it
// equals STREAM_PLANNER_TPB (the walker's planner-thread grain) so the
// target_work formula below correctly sizes work per walker WG. If you
// change STREAM_PLANNER_TPB in ba_stream_plan.ts, change this together
// — they are coupled, not coincidentally equal.
const TPB: u32 = {{ planner_tpb }}u;
const NUM_THREADS: u32 = {{ num_threads }}u;
const MIN_ITERS_PER_WG: u32 = {{ min_iters_per_wg }}u;
const MAX_WORKGROUPS: u32 = {{ max_workgroups }}u;

@group(0) @binding(0) var<storage, read>       sorted_count_list: array<u32>;
@group(0) @binding(1) var<storage, read_write> cumulative_adds:   array<u32>;
@group(0) @binding(2) var<storage, read_write> planner_meta:      array<u32>;
@group(0) @binding(3) var<uniform>             params:            vec4<u32>;

var<workgroup> wg_sums: array<u32, {{ planner_tpb }}>;

fn ceil_div(a: u32, b: u32) -> u32 {
    return (a + b - 1u) / b;
}

@compute @workgroup_size({{ planner_tpb }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>) {
    let tid = lid.x;
    let num_dense = planner_meta[1];

    // No early return — workgroupBarrier requires uniform control flow.
    // When num_dense==0, chunk/my_start/my_end all become 0 and the
    // loops execute zero iterations, producing the correct result.
    let chunk = max(ceil_div(num_dense, TPB), 1u);
    let my_start = min(tid * chunk, num_dense);
    let my_end = min(my_start + chunk, num_dense);

    // Phase A: sum (count - 1) across this thread's chunk.
    var local_sum: u32 = 0u;
    var _phaseA_iter: u32 = 0u;
    for (var i: u32 = my_start; i < my_end; i = i + 1u) {
        if (_phaseA_iter >= 65536u) { break; }
        _phaseA_iter = _phaseA_iter + 1u;
        let c = sorted_count_list[i];
        local_sum += c - 1u;
    }
    wg_sums[tid] = local_sum;
    workgroupBarrier();

    // Phase B: Hillis-Steele inclusive scan over wg_sums.
    for (var stride: u32 = 1u; stride < TPB; stride = stride * 2u) {
        var add_val: u32 = 0u;
        if (tid >= stride) {
            add_val = wg_sums[tid - stride];
        }
        workgroupBarrier();
        if (tid >= stride) {
            wg_sums[tid] = wg_sums[tid] + add_val;
        }
        workgroupBarrier();
    }

    // Phase C: per-element exclusive prefix within each chunk.
    let block_prefix = select(0u, wg_sums[tid - 1u], tid > 0u);
    var running: u32 = block_prefix;
    var _phaseC_iter: u32 = 0u;
    for (var i: u32 = my_start; i < my_end; i = i + 1u) {
        if (_phaseC_iter >= 65536u) { break; }
        _phaseC_iter = _phaseC_iter + 1u;
        cumulative_adds[i] = running;
        let c = sorted_count_list[i];
        running += c - 1u;
    }

    // Last thread writes total_adds + dispatch args.
    if (tid == TPB - 1u) {
        let total_adds = wg_sums[TPB - 1u];
        planner_meta[2] = total_adds;

        let target_work = TPB * {{ s }}u * MIN_ITERS_PER_WG;
        var nwg: u32 = 1u;
        if (total_adds > target_work) {
            nwg = total_adds / target_work;
        }
        nwg = min(nwg, MAX_WORKGROUPS);
        nwg = max(nwg, 1u);
        planner_meta[3] = nwg;

        planner_meta[12] = nwg;
        planner_meta[13] = 1u;
        planner_meta[14] = 1u;
    }

    {{{ recompile }}}
}
`;

export const ba_planner_meta_fixup = `// Bucket-accumulate planner stage 1.1b: meta fixup.
//
// Single thread reads the final atomic counters from classify and writes
// derived indirect-dispatch args into planner_meta.

@group(0) @binding(0) var<storage, read_write> planner_meta: array<u32>;

fn ceil_div(a: u32, b: u32) -> u32 {
    return (a + b - 1u) / b;
}

@compute @workgroup_size(1)
fn main() {
    let num_size1 = planner_meta[0];

    planner_meta[8]  = ceil_div(num_size1, 64u);
    planner_meta[9]  = 1u;
    planner_meta[10] = 1u;

    {{{ recompile }}}
}
`;

export const ba_planner_partition_task = `// Stream-walker planner stage 1.6: per-thread task partition (KNOB 2).
//
// Design-knob variation on the stream-walker plan (§1.4 / §8): instead of
// having ba_stream_walker compute its S task cuts at kernel init (9 binary
// searches per thread), hoist that work into this dedicated planner kernel.
// The walker then reads precomputed cuts from \`task_cuts\` rather than
// binary-searching cumulative_adds itself.
//
// For each active walker thread t this refines its work range
// [thread_cuts[t], thread_cuts[t+1]) into S equal-work tasks by binary
// searching cumulative_adds, and writes S+1 cut points (each a
// (sorted_bucket, adds_offset) pair) so the walker can read cut k and k+1
// as the [start, end) of task k. The cut encoding matches thread_cuts:
// adds_offset is measured in the (count-1) adds-prefix space of the bucket.

// thread_cuts are produced by ba_planner_partition_thread at THREAD_TPB
// granularity, so NUM_THREADS = nwg * THREAD_TPB. WALKER_TPB only governs
// the walker's own workgroup_size; the indirect dispatch count emitted
// below is nwg * THREAD_TPB / WALKER_TPB workgroups. Both constants come
// from ba_stream_plan.ts via the generator, NOT inlined.
const THREAD_TPB: u32 = {{ thread_tpb }}u;
const WALKER_TPB: u32 = {{ walker_tpb }}u;
const S: u32 = {{ s }}u;              // tasks per thread
const CUTS: u32 = S + 1u;             // cut points per thread

@group(0) @binding(0) var<storage, read>       sorted_count_list: array<u32>;
@group(0) @binding(1) var<storage, read>       cumulative_adds:   array<u32>;
@group(0) @binding(2) var<storage, read>       thread_cuts:       array<u32>;
@group(0) @binding(3) var<storage, read_write> planner_meta:      array<u32>;
@group(0) @binding(4) var<storage, read_write> task_cuts:         array<u32>;
@group(0) @binding(5) var<uniform>             params:            vec4<u32>;

// Binary search for the lowest bucket b in [lo_b, hi_b) whose inclusive
// add-prefix end (cumulative_adds[b] + count[b] - 1) reaches \`cut_target\`,
// then resolve the within-bucket offset. Mirrors ba_planner_partition_thread.
fn resolve_cut(cut_target: u32, lo_b: u32, hi_b: u32, num_dense: u32) -> vec2<u32> {
    var lo: u32 = lo_b;
    var hi: u32 = hi_b;
    var _bs_iter: u32 = 0u;
    while (lo < hi) {
        if (_bs_iter >= 64u) { break; }
        _bs_iter = _bs_iter + 1u;
        let mid = (lo + hi) / 2u;
        let cum_end = cumulative_adds[mid] + sorted_count_list[mid] - 1u;
        if (cum_end < cut_target) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }
    let cut_bucket = min(lo, num_dense - 1u);
    var cut_offset: u32 = 0u;
    if (cut_target > cumulative_adds[cut_bucket]) {
        cut_offset = cut_target - cumulative_adds[cut_bucket];
    }
    return vec2<u32>(cut_bucket, cut_offset);
}

@compute @workgroup_size({{ thread_tpb }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let t = gid.x;
    let nwg = planner_meta[3];
    let num_dense = planner_meta[1];
    let num_active_threads = nwg * THREAD_TPB;

    // Thread 0 emits the walker's indirect-dispatch args (workgroups of
    // WALKER_TPB needed to cover num_active_threads walker threads).
    if (t == 0u) {
        planner_meta[15] = (num_active_threads + WALKER_TPB - 1u) / WALKER_TPB;
        planner_meta[16] = 1u;
        planner_meta[17] = 1u;
    }

    if (t >= num_active_threads) { return; }

    let first_bucket = thread_cuts[2u * t + 0u];
    let first_off    = thread_cuts[2u * t + 1u];

    // The last active thread's end is the global work end. partition_thread
    // fills only nwg*256 start cuts (no end sentinel at index nwg*256), so
    // reading thread_cuts[t+1] there would pick up a stale slot.
    let total_adds = planner_meta[2];
    var last_bucket: u32;
    var last_off: u32;
    if (t + 1u >= num_active_threads) {
        last_bucket = num_dense - 1u;
        last_off    = total_adds - cumulative_adds[num_dense - 1u];
    } else {
        last_bucket = thread_cuts[2u * (t + 1u) + 0u];
        last_off    = thread_cuts[2u * (t + 1u) + 1u];
    }

    let start_adds = cumulative_adds[first_bucket] + first_off;
    let end_adds   = cumulative_adds[last_bucket] + last_off;
    let thread_total = end_adds - start_adds;

    let hi_b = min(last_bucket + 1u, num_dense);
    let base = t * CUTS * 2u;
    for (var k: u32 = 0u; k < CUTS; k = k + 1u) {
        let cut_target = start_adds + (k * thread_total) / S;
        let cut = resolve_cut(cut_target, first_bucket, hi_b, num_dense);
        task_cuts[base + k * 2u + 0u] = cut.x;
        task_cuts[base + k * 2u + 1u] = cut.y;
    }

    {{{ recompile }}}
}
`;

export const ba_planner_partition_thread = `// Bucket-accumulate planner stage 1.5: per-thread partition.
//
// Refines workgroup cuts into per-thread cuts. Each thread t in
// workgroup w binary-searches cumulative_adds within its workgroup's
// range to find the bucket where its share of work starts.

const TPB: u32 = {{ workgroup_size }}u;

@group(0) @binding(0) var<storage, read>       sorted_count_list: array<u32>;
@group(0) @binding(1) var<storage, read>       cumulative_adds:   array<u32>;
@group(0) @binding(2) var<storage, read>       wg_cuts:           array<u32>;
@group(0) @binding(3) var<storage, read>       planner_meta:      array<u32>;
@group(0) @binding(4) var<storage, read_write> thread_cuts:       array<u32>;
@group(0) @binding(5) var<uniform>             params:            vec4<u32>;

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let t = lid.x;
    let wg = wid.x;
    let num_workgroups = planner_meta[3];
    let total_adds = planner_meta[2];
    let num_dense = planner_meta[1];

    if (wg >= num_workgroups) { return; }

    // wg_cuts[2*w] is the END cut for workgroup w (where its work ends).
    // Start of wg 0 is bucket 0; start of wg w>0 is wg_cuts[2*(w-1)].
    let wg_start_adds = (wg * total_adds) / num_workgroups;
    let wg_end_adds = ((wg + 1u) * total_adds) / num_workgroups;
    let wg_total = wg_end_adds - wg_start_adds;

    let cut_target = wg_start_adds + ((t * wg_total) / TPB);

    var wg_lo_bucket: u32 = 0u;
    if (wg > 0u) {
        wg_lo_bucket = wg_cuts[2u * (wg - 1u) + 0u];
    }
    let wg_hi_bucket = min(wg_cuts[2u * wg + 0u] + 1u, num_dense);

    // Binary search for the bucket containing this thread's cut_target.
    var lo: u32 = wg_lo_bucket;
    var hi: u32 = wg_hi_bucket;
    var _bs_iter: u32 = 0u;
    while (lo < hi) {
        if (_bs_iter >= 64u) { break; }
        _bs_iter = _bs_iter + 1u;
        let mid = (lo + hi) / 2u;
        let cum_end = cumulative_adds[mid] + sorted_count_list[mid] - 1u;
        if (cum_end < cut_target) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }

    let cut_bucket = min(lo, num_dense - 1u);
    var cut_offset: u32 = 0u;
    if (cut_target > cumulative_adds[cut_bucket]) {
        cut_offset = cut_target - cumulative_adds[cut_bucket];
    }

    let flat = wg * TPB + t;
    thread_cuts[2u * flat + 0u] = cut_bucket;
    thread_cuts[2u * flat + 1u] = cut_offset;

    {{{ recompile }}}
}
`;

export const ba_planner_partition_wg = `// Bucket-accumulate planner stage 1.4: workgroup partition.
//
// For each workgroup w in [0, num_workgroups), binary-search
// cumulative_adds to find the bucket index where this workgroup's
// share of total_adds starts. Writes wg_cuts[2*w+0] = bucket_idx,
// wg_cuts[2*w+1] = offset within that bucket's adds.

@group(0) @binding(0) var<storage, read>       sorted_count_list: array<u32>;
@group(0) @binding(1) var<storage, read>       cumulative_adds:   array<u32>;
@group(0) @binding(2) var<storage, read>       planner_meta:      array<u32>;
@group(0) @binding(3) var<storage, read_write> wg_cuts:           array<u32>;
@group(0) @binding(4) var<uniform>             params:            vec4<u32>;

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>) {
    let w = lid.x;
    let num_workgroups = planner_meta[3];
    let total_adds = planner_meta[2];
    let num_dense = planner_meta[1];

    if (w >= num_workgroups) { return; }

    let cut_target = ((w + 1u) * total_adds) / num_workgroups;

    // Binary search for smallest i with cumulative_adds[i] + (sorted_count_list[i] - 1) >= cut_target,
    // i.e. the bucket whose cumulative range contains the cut_target.
    var lo: u32 = 0u;
    var hi: u32 = num_dense;
    var _bs_iter: u32 = 0u;
    while (lo < hi) {
        if (_bs_iter >= 64u) { break; }
        _bs_iter = _bs_iter + 1u;
        let mid = (lo + hi) / 2u;
        let cum_end = cumulative_adds[mid] + sorted_count_list[mid] - 1u;
        if (cum_end < cut_target) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }

    let cut_bucket = min(lo, num_dense - 1u);
    var cut_offset: u32 = 0u;
    if (cut_target > cumulative_adds[cut_bucket]) {
        cut_offset = cut_target - cumulative_adds[cut_bucket];
    }

    wg_cuts[2u * w + 0u] = cut_bucket;
    wg_cuts[2u * w + 1u] = cut_offset;

    {{{ recompile }}}
}
`;

export const ba_planner_radix_count = `// Bucket-accumulate planner stage 1.2a: radix histogram.
//
// Per-tile 256-bin histogram of the radix digit at the current pass's
// byte position. Sorts descending by using the bitwise complement of
// count as the sort key.
//
// Dispatch: ceil(num_dense / TILE_SIZE) workgroups of 256 threads.
// Each thread processes TILE_SIZE / 256 elements (coarsened).

const TILE_SIZE: u32 = {{ tile_size }}u;

@group(0) @binding(0) var<storage, read>       in_count:     array<u32>;
@group(0) @binding(1) var<storage, read_write> radix_hist:   array<u32>;
@group(0) @binding(2) var<storage, read>       planner_meta: array<u32>;
@group(0) @binding(3) var<uniform>             params:       vec4<u32>;

var<workgroup> hist: array<atomic<u32>, 256>;

@compute @workgroup_size(256)
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let tile = wid.x;
    let pass_idx = params.x;
    let num_dense = planner_meta[1];

    atomicStore(&hist[tid], 0u);
    workgroupBarrier();

    let base = tile * TILE_SIZE;
    let end = min(base + TILE_SIZE, num_dense);
    for (var i: u32 = base + tid; i < end; i = i + 256u) {
        let count_key = ~in_count[i];
        let digit = (count_key >> (pass_idx * 8u)) & 0xFFu;
        atomicAdd(&hist[digit], 1u);
    }
    workgroupBarrier();

    radix_hist[tile * 256u + tid] = atomicLoad(&hist[tid]);

    {{{ recompile }}}
}
`;

export const ba_planner_radix_scan = `// Bucket-accumulate planner stage 1.2b: column-major radix scan.
//
// Corrected digit-major scan for GPU radix sort. One workgroup of 256
// threads, one thread per digit. After this kernel:
//   radix_hist[tile * 256 + digit] = global output offset where this
//   tile's items with this digit should be scattered.
//
// Three phases:
//   A — each thread sums its digit across all tiles → digit_total[d]
//   B — Hillis-Steele inclusive scan of digit_total → cross-digit base
//   C — per-digit column scan across tiles (sequential exclusive prefix)

@group(0) @binding(0) var<storage, read_write> radix_hist:   array<u32>;
@group(0) @binding(1) var<storage, read>       planner_meta: array<u32>;
@group(0) @binding(2) var<uniform>             params:       vec4<u32>;

var<workgroup> digit_total: array<u32, 256>;

@compute @workgroup_size(256)
fn main(@builtin(local_invocation_id) lid: vec3<u32>) {
    let d = lid.x;
    let num_tiles = params.x;

    // Phase A: sum this digit across all tiles.
    var total: u32 = 0u;
    for (var t: u32 = 0u; t < num_tiles; t = t + 1u) {
        total += radix_hist[t * 256u + d];
    }
    digit_total[d] = total;
    workgroupBarrier();

    // Phase B: Hillis-Steele inclusive scan over digit_total.
    for (var stride: u32 = 1u; stride < 256u; stride = stride * 2u) {
        var add_val: u32 = 0u;
        if (d >= stride) {
            add_val = digit_total[d - stride];
        }
        workgroupBarrier();
        if (d >= stride) {
            digit_total[d] = digit_total[d] + add_val;
        }
        workgroupBarrier();
    }
    // digit_total[d] = inclusive prefix sum of all digit totals up to d.
    // Exclusive prefix for digit d = inclusive[d] - own contribution.
    let base = digit_total[d] - total;

    // Phase C: column scan — exclusive prefix within this digit across tiles.
    var running: u32 = base;
    for (var t: u32 = 0u; t < num_tiles; t = t + 1u) {
        let addr = t * 256u + d;
        let old_val = radix_hist[addr];
        radix_hist[addr] = running;
        running += old_val;
    }

    {{{ recompile }}}
}
`;

export const ba_planner_radix_scatter = `// Bucket-accumulate planner stage 1.2c: radix scatter.
//
// Scatters (bucket_idx, count) pairs from input to output arrays based
// on the digit at the current pass's byte position. Uses per-tile
// atomic cursors seeded from the scanned radix_hist.
//
// Dispatch: ceil(num_dense / TILE_SIZE) workgroups of 256 threads.

const TILE_SIZE: u32 = {{ tile_size }}u;

@group(0) @binding(0) var<storage, read>       in_bucket:    array<u32>;
@group(0) @binding(1) var<storage, read>       in_count:     array<u32>;
@group(0) @binding(2) var<storage, read>       radix_hist:   array<u32>;
@group(0) @binding(3) var<storage, read_write> out_bucket:   array<u32>;
@group(0) @binding(4) var<storage, read_write> out_count:    array<u32>;
@group(0) @binding(5) var<storage, read>       planner_meta: array<u32>;
@group(0) @binding(6) var<uniform>             params:       vec4<u32>;

var<workgroup> local_cursor: array<atomic<u32>, 256>;

@compute @workgroup_size(256)
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let tile = wid.x;
    let pass_idx = params.x;
    let num_dense = planner_meta[1];

    // Seed each digit's cursor to 0 (offset is added from radix_hist).
    atomicStore(&local_cursor[tid], 0u);
    workgroupBarrier();

    let base = tile * TILE_SIZE;
    let end = min(base + TILE_SIZE, num_dense);
    for (var i: u32 = base + tid; i < end; i = i + 256u) {
        let count_key = ~in_count[i];
        let digit = (count_key >> (pass_idx * 8u)) & 0xFFu;
        let slot = atomicAdd(&local_cursor[digit], 1u) + radix_hist[tile * 256u + digit];
        out_bucket[slot] = in_bucket[i];
        out_count[slot] = in_count[i];
    }

    {{{ recompile }}}
}
`;

export const ba_planner_v2_emit = `// MSM bucket-accumulate planner — pass B of 2: parallel plan emit.
//
// Dispatch (ceil(BW/TPB), NUM_WINDOWS): one workgroup per (bucket-group,
// window), one thread per bucket. Reads the per-bucket offsets pass A
// (ba_planner_v2_offsets) computed and emits the pair-block / scatter /
// carry plan entries — the O(pairs) work, now spread across NUM_GROUPS *
// NUM_WINDOWS workgroups instead of one workgroup per window.
//
// "pair_block": the unit of fused-affine-add work. The pair-tree level loop
// pulls pairs S at a time (one block) and feeds them through a shared
// batched inversion. Each window's pairs are packed into
// \`pair_blocks_per_window\` blocks of S pairs each; \`pair_block_plan\` holds
// 2*S u32 per block (S left-indices + S right-indices).
//
// The window-local pair prefix is derived as
//   new_offsets[b] - w*wstride - carry_off[b].
// After emitting, the window's NUM_GROUPS workgroups cooperatively pad
// the plan tail (lever-E self-pad) with the pad trio. The emit writes
// plan slots [0, total_pairs) and the pad writes [total_pairs, block
// slots) — disjoint ranges, so no ordering between them is needed.

const TPB: u32 = {{ workgroup_size }}u;
const BW: u32 = {{ buckets_per_window }}u;
const NUM_WINDOWS: u32 = {{ num_windows }}u;
const NUM_GROUPS: u32 = {{ num_groups }}u;
const PAIR_CAP: u32 = {{ pair_cap }}u;
const S: u32 = {{ s }}u;

@group(0) @binding(0) var<storage, read>       counts:       array<u32>;
@group(0) @binding(1) var<storage, read>       offsets:      array<u32>;
@group(0) @binding(2) var<storage, read>       carry_off:    array<u32>;
@group(0) @binding(3) var<storage, read>       new_offsets:  array<u32>;
@group(0) @binding(4) var<storage, read>       plan_meta:    array<u32>;
@group(0) @binding(5) var<storage, read_write> pair_block_plan: array<u32>;
@group(0) @binding(6) var<storage, read_write> scatter_plan:    array<u32>;
@group(0) @binding(7) var<storage, read_write> carry_plan:      array<u32>;
@group(0) @binding(8) var<uniform>             params:          vec4<u32>;
@group(0) @binding(9) var<uniform>             pad_params:      vec4<u32>;

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let bg = wid.x;
    let w = wid.y;
    if (w >= NUM_WINDOWS) { return; }

    let pair_blocks_per_window = params.x;
    let carries_per_window     = params.y;
    let wstride                = params.w;
    let window_block_base      = w * pair_blocks_per_window;
    let window_carry_base      = w * carries_per_window;

    // Emit this bucket's pair / carry plan entries.
    let b_local = bg * TPB + tid;
    if (b_local < BW) {
        let b = w * BW + b_local;
        let n = counts[b];
        let pc = n / 2u;
        let cf = select(n & 1u, 0u, n == 1u);
        let bucket_base = offsets[b];
        let no = new_offsets[b];
        let co = carry_off[b];
        let po = (no - w * wstride) - co;   // window-local pair prefix

        for (var j: u32 = 0u; j < PAIR_CAP; j = j + 1u) {
            if (j >= pc) { break; }
            let slot_in_window = po + j;
            let global_block  = window_block_base + slot_in_window / S;
            let slot_in_block = slot_in_window % S;
            let flat_slot     = global_block * S + slot_in_block;
            pair_block_plan[2u * flat_slot + 0u] = bucket_base + 2u * j;
            pair_block_plan[2u * flat_slot + 1u] = bucket_base + 2u * j + 1u;
            scatter_plan[flat_slot] = no + j;
        }
        if (cf != 0u) {
            let cs = window_carry_base + co;
            carry_plan[2u * cs + 0u] = bucket_base + n - 1u;
            carry_plan[2u * cs + 1u] = no + pc;
        }
    }

    // Lever-E self-pad: the window's NUM_GROUPS workgroups cooperatively
    // fill the plan tail past the real entries with the pad trio.
    let pad_l = pad_params.x;
    let pad_r = pad_params.y;
    let pad_d = pad_params.z;
    let total_pairs   = plan_meta[3u * w + 0u];
    let total_carries = plan_meta[3u * w + 1u];
    let block_slots   = pair_blocks_per_window * S;
    let stripe = bg * TPB + tid;
    let pad_stride = NUM_GROUPS * TPB;
    for (var sp: u32 = total_pairs + stripe; sp < block_slots; sp = sp + pad_stride) {
        let flat = window_block_base * S + sp;
        pair_block_plan[2u * flat + 0u] = pad_l;
        pair_block_plan[2u * flat + 1u] = pad_r;
        scatter_plan[flat] = pad_d;
    }
    for (var sc: u32 = total_carries + stripe; sc < carries_per_window; sc = sc + pad_stride) {
        let cflat = window_carry_base + sc;
        carry_plan[2u * cflat + 0u] = pad_l;
        carry_plan[2u * cflat + 1u] = pad_d;
    }

    {{{ recompile }}}
}
`;

export const ba_planner_v2_offsets = `// MSM bucket-accumulate planner — pass A of 2: per-window scan + offsets.
//
// One workgroup per Pippenger window. Computes, for every bucket, the
// window-local prefix offsets the emit pass (ba_planner_v2_emit) needs,
// plus new_counts / new_offsets and the per-window plan_meta totals — but
// NOT the O(pairs) pair_block / scatter / carry plans, which the emit
// pass writes in parallel across buckets.
//
// Phase A  per-thread tally of (pair, carry, new) counts.
// Phase B  workgroup Hillis-Steele scan of the 3 per-thread totals.
// Phase C  per bucket: write new_counts, new_offsets, carry_off. The emit
//          pass derives the pair prefix as new_offsets - w*wstride
//          - carry_off (pc + cf = nc, so the pair prefix is the new
//          prefix minus the carry prefix).
// Phase D  window totals + level-wide indirect-dispatch args.
//
// O(BW) per window — flat in n, so the NUM_WINDOWS-workgroup dispatch is
// not an occupancy bottleneck (the O(pairs) work is all in the emit pass).

const TPB: u32 = {{ workgroup_size }}u;
const BW: u32 = {{ buckets_per_window }}u;
const PER_THREAD: u32 = {{ per_thread }}u;
const NUM_WINDOWS: u32 = {{ num_windows }}u;

@group(0) @binding(0) var<storage, read>       counts:      array<u32>;
@group(0) @binding(1) var<storage, read_write> carry_off:   array<u32>;
@group(0) @binding(2) var<storage, read_write> new_counts:  array<u32>;
@group(0) @binding(3) var<storage, read_write> new_offsets: array<u32>;
@group(0) @binding(4) var<storage, read_write> plan_meta:   array<u32>;
@group(0) @binding(5) var<uniform>             params:      vec4<u32>;

var<workgroup> pair_scan:  array<u32, {{ workgroup_size }}>;
var<workgroup> carry_scan: array<u32, {{ workgroup_size }}>;
var<workgroup> new_scan:   array<u32, {{ workgroup_size }}>;

fn ceil_div(a: u32, b: u32) -> u32 {
    return (a + b - 1u) / b;
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let w = wid.x;
    if (w >= NUM_WINDOWS) { return; }

    let pair_blocks_per_window = params.x;
    let carries_per_window     = params.y;
    let wstride                = params.w;
    let window_bucket_base = w * BW;

    // Phase A: per-thread tally over this thread's PER_THREAD buckets.
    var sum_p: u32 = 0u;
    var sum_c: u32 = 0u;
    var sum_n: u32 = 0u;
    for (var k: u32 = 0u; k < PER_THREAD; k = k + 1u) {
        let b_local = tid * PER_THREAD + k;
        if (b_local < BW) {
            let n = counts[window_bucket_base + b_local];
            let pc = n / 2u;
            let cf = select(n & 1u, 0u, n == 1u);
            sum_p += pc;
            sum_c += cf;
            sum_n += pc + cf;
        }
    }

    // Phase B: workgroup Hillis-Steele inclusive scan (3 interleaved).
    pair_scan[tid] = sum_p;
    carry_scan[tid] = sum_c;
    new_scan[tid] = sum_n;
    workgroupBarrier();
    for (var stride: u32 = 1u; stride < TPB; stride = stride * 2u) {
        var add_p: u32 = 0u;
        var add_c: u32 = 0u;
        var add_n: u32 = 0u;
        if (tid >= stride) {
            add_p = pair_scan[tid - stride];
            add_c = carry_scan[tid - stride];
            add_n = new_scan[tid - stride];
        }
        workgroupBarrier();
        if (tid >= stride) {
            pair_scan[tid] = pair_scan[tid] + add_p;
            carry_scan[tid] = carry_scan[tid] + add_c;
            new_scan[tid] = new_scan[tid] + add_n;
        }
        workgroupBarrier();
    }
    var local_carry_off: u32 = carry_scan[tid] - sum_c;
    var local_new_off: u32 = new_scan[tid] - sum_n;

    // Phase D: window totals + level-wide indirect-dispatch args.
    if (tid == TPB - 1u) {
        plan_meta[3u * w + 0u] = pair_scan[tid];
        plan_meta[3u * w + 1u] = carry_scan[tid];
        plan_meta[3u * w + 2u] = new_scan[tid];
    }
    if (w == 0u && tid == 0u) {
        let wgi = max(params.z, 1u);
        let d = 3u * NUM_WINDOWS;
        plan_meta[d + 0u] = ceil_div(NUM_WINDOWS * pair_blocks_per_window, wgi);
        plan_meta[d + 1u] = 1u;
        plan_meta[d + 2u] = 1u;
        plan_meta[d + 3u] = ceil_div(NUM_WINDOWS * carries_per_window, wgi);
        plan_meta[d + 4u] = 1u;
        plan_meta[d + 5u] = 1u;
    }

    // Phase C: per-bucket offsets — consumed by the emit pass.
    for (var k: u32 = 0u; k < PER_THREAD; k = k + 1u) {
        let b_local = tid * PER_THREAD + k;
        if (b_local >= BW) { break; }
        let b = window_bucket_base + b_local;
        let n = counts[b];
        let pc = n / 2u;
        let cf = select(n & 1u, 0u, n == 1u);
        new_counts[b] = pc + cf;
        new_offsets[b] = w * wstride + local_new_off;
        carry_off[b] = local_carry_off;
        local_carry_off += cf;
        local_new_off += pc + cf;
    }

    {{{ recompile }}}
}
`;

export const ba_reduce_coop = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> inverse_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

{{> field8_funcs }}

// Single-dispatch cooperative bucket reduction for small c (STRIDE <= 128).
//
// One workgroup per window computes W = sum_{i=0..STRIDE-1} (i+1)*B[i] in
// shared memory, in ONE dispatch (replacing reduceInit's ~21-launch tail).
//
// SEGMENTED RUNNING-SUM (2N adds, no doublings in the bulk):
//   Phase 1: WG = G threads, each does a serial running-sum over its SS =
//     STRIDE/G contiguous buckets -> (seg_total[t], seg_wsum[t]) with LOCAL
//     weights 1..SS. Cost: 2*SS adds/thread = 2*STRIDE adds/window total.
//   Phase 2: a (total, wsum) tree over the G partials. Combining segment p
//     (left) with p+width (right, offset width*SS buckets):
//        ws = ws_L + ws_R + (width*SS)*tot_R ;  tot = tot_L + tot_R
//     so the ONLY doublings are log2(width*SS) per combine, O(G) per window.
//   Root: seg_wsum[0] = W. One inversion to affine.
//
// Inversion-free Jacobian adds; Z == 0 = point at infinity (seeded from
// is_present). Montgomery throughout. Falls back to the multi-dispatch reduce
// above STRIDE = 128 (shared-memory budget).

const PG: u32 = 2u;
const WG: u32 = {{ workgroup_size }}u;   // = G, segments per window
const STRIDE: u32 = {{ stride }}u;
const SS: u32 = {{ ss }}u;               // buckets per segment = STRIDE / G
const LOG2_SS: u32 = {{ log2_ss }}u;

@group(0) @binding(0) var<storage, read_write> red_buf:    array<vec4<u32>>;
@group(0) @binding(1) var<storage, read_write> red_z:      array<vec4<u32>>;
@group(0) @binding(2) var<storage, read>       is_present: array<u32>;
@group(0) @binding(3) var<uniform>             cparams:    vec4<u32>;
// cparams = (M (red_buf element stride), _, num_windows, _)

fn load_x(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn load_y(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * M + PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn store_x(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}
fn store_y(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * M + PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}
fn store_z(idx: u32, val: array<u32, 8>) {
    let base = PG * idx;
    red_z[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_z[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn fr_select_f8(a: array<u32, 8>, b: array<u32, 8>, cond: bool) -> array<u32, 8> {
    return array<u32, 8>(
        select(a[0], b[0], cond), select(a[1], b[1], cond),
        select(a[2], b[2], cond), select(a[3], b[3], cond),
        select(a[4], b[4], cond), select(a[5], b[5], cond),
        select(a[6], b[6], cond), select(a[7], b[7], cond));
}
fn fr_dbl_f8(a: array<u32, 8>) -> array<u32, 8> { return fr_add_f8(a, a); }

struct Jac { x: array<u32, 8>, y: array<u32, 8>, z: array<u32, 8>, }

fn jac_double(p: Jac) -> Jac {
    let A = montgomery_product_f8(p.x, p.x);
    let B = montgomery_product_f8(p.y, p.y);
    let C = montgomery_product_f8(B, B);
    let XpB = fr_add_f8(p.x, B);
    let s = fr_sub_f8(montgomery_product_f8(XpB, XpB), fr_add_f8(A, C));
    let D = fr_dbl_f8(s);
    let E = fr_add_f8(fr_dbl_f8(A), A);
    let F = montgomery_product_f8(E, E);
    let X3 = fr_sub_f8(F, fr_dbl_f8(D));
    let C8 = fr_dbl_f8(fr_dbl_f8(fr_dbl_f8(C)));
    let Y3 = fr_sub_f8(montgomery_product_f8(E, fr_sub_f8(D, X3)), C8);
    let Z3 = fr_dbl_f8(montgomery_product_f8(p.y, p.z));
    return Jac(X3, Y3, Z3);
}

fn jac_add_raw(p1: Jac, p2: Jac) -> Jac {
    let Z1Z1 = montgomery_product_f8(p1.z, p1.z);
    let Z2Z2 = montgomery_product_f8(p2.z, p2.z);
    let U1 = montgomery_product_f8(p1.x, Z2Z2);
    let U2 = montgomery_product_f8(p2.x, Z1Z1);
    let S1 = montgomery_product_f8(montgomery_product_f8(p1.y, p2.z), Z2Z2);
    let S2 = montgomery_product_f8(montgomery_product_f8(p2.y, p1.z), Z1Z1);
    let H = fr_sub_f8(U2, U1);
    let twoH = fr_dbl_f8(H);
    let I = montgomery_product_f8(twoH, twoH);
    let J = montgomery_product_f8(H, I);
    let r = fr_dbl_f8(fr_sub_f8(S2, S1));
    let V = montgomery_product_f8(U1, I);
    let X3 = fr_sub_f8(fr_sub_f8(montgomery_product_f8(r, r), J), fr_dbl_f8(V));
    let S1J = montgomery_product_f8(S1, J);
    let Y3 = fr_sub_f8(montgomery_product_f8(r, fr_sub_f8(V, X3)), fr_dbl_f8(S1J));
    let ZpZ = fr_add_f8(p1.z, p2.z);
    let Z3 = montgomery_product_f8(fr_sub_f8(fr_sub_f8(montgomery_product_f8(ZpZ, ZpZ), Z1Z1), Z2Z2), H);
    return Jac(X3, Y3, Z3);
}

fn jac_add(dst: Jac, src: Jac) -> Jac {
    let sum = jac_add_raw(dst, src);
    let src_inf = is_zero_f8(src.z);
    let dst_inf = is_zero_f8(dst.z);
    var rx = fr_select_f8(sum.x, src.x, dst_inf);
    var ry = fr_select_f8(sum.y, src.y, dst_inf);
    var rz = fr_select_f8(sum.z, src.z, dst_inf);
    rx = fr_select_f8(rx, dst.x, src_inf);
    ry = fr_select_f8(ry, dst.y, src_inf);
    rz = fr_select_f8(rz, dst.z, src_inf);
    return Jac(rx, ry, rz);
}

// G segment partials: (total, wsum) each.
var<workgroup> seg_tot_x: array<array<u32, 8>, WG>;
var<workgroup> seg_tot_y: array<array<u32, 8>, WG>;
var<workgroup> seg_tot_z: array<array<u32, 8>, WG>;
var<workgroup> seg_ws_x: array<array<u32, 8>, WG>;
var<workgroup> seg_ws_y: array<array<u32, 8>, WG>;
var<workgroup> seg_ws_z: array<array<u32, 8>, WG>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(workgroup_id) wgid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
    let w = wgid.x;
    let t = lid.x;
    let M = cparams.x;
    let num_windows = cparams.z;
    if (w >= num_windows) { return; }
    let base = w * STRIDE;
    let zero = array<u32, 8>(0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);

    // Phase 1: serial running-sum over this thread's SS contiguous buckets,
    // from the top down. 2*SS adds, no doublings. Both accumulators stay in
    // registers and are published to shared exactly once at the end, so the only
    // cross-thread shared traffic is the single write per slot + the barrier.
    var acc = Jac(zero, zero, zero);   // running suffix sum within the segment
    var ws = Jac(zero, zero, zero);    // running weighted sum
    let seg_start = t * SS;
    var local: u32 = SS;
    loop {
        if (local == 0u) { break; }
        local = local - 1u;
        let slot = base + seg_start + local;
        var bz = zero;
        if (is_present[slot] != 0u) { bz = get_r_f8(); }
        let b = Jac(load_x(slot, M), load_y(slot, M), bz);
        acc = jac_add(acc, b);     // acc = suffix sum within the segment
        ws = jac_add(ws, acc);     // ws += acc
    }
    seg_tot_x[t] = acc.x; seg_tot_y[t] = acc.y; seg_tot_z[t] = acc.z;
    seg_ws_x[t] = ws.x; seg_ws_y[t] = ws.y; seg_ws_z[t] = ws.z;
    workgroupBarrier();

    // Phase 2: thread 0 combines the G segment partials serially. A cooperative
    // shared-memory tree here flaked on M2 — a workgroup-memory issue that scaled
    // with tree depth (G=8 ~1/8 wrong, G=32 ~1/2), while the multi-dispatch
    // reduce sharing the same jac_add is reliable. The serial combine has no
    // cross-thread shared writes and is reliable; it is cheap (~3G adds).
    //
    //   W = sum_seg seg_ws[seg] + SS * sum_seg seg*seg_tot[seg] = A + SS*B,
    //   A = sum_seg seg_ws[seg],
    //   B = sum_seg seg*seg_tot[seg] = sum_{j=1..G-1} suffix(j),
    //       suffix(j) = sum_{seg>=j} seg_tot[seg]   (running-sum identity).
    // Bucket i = seg*SS + m then carries global weight (seg*SS + m + 1) = i+1.
    if (t == 0u) {
        var suffix = Jac(zero, zero, zero);
        var bsum = Jac(zero, zero, zero);
        var j: u32 = WG;
        loop {
            if (j <= 1u) { break; }
            j = j - 1u;
            suffix = jac_add(suffix, Jac(seg_tot_x[j], seg_tot_y[j], seg_tot_z[j]));
            bsum = jac_add(bsum, suffix);
        }
        var d: u32 = 0u;
        loop {
            if (d >= LOG2_SS) { break; }
            bsum = jac_double(bsum);   // bsum = SS * B
            d = d + 1u;
        }
        var w_acc = bsum;
        var seg: u32 = 0u;
        loop {
            if (seg >= WG) { break; }
            w_acc = jac_add(w_acc, Jac(seg_ws_x[seg], seg_ws_y[seg], seg_ws_z[seg]));
            seg = seg + 1u;
        }
        // Write the Jacobian window sum at slot \`base\`; ba_reduce_jac_finalize
        // does the single per-window inversion to affine.
        store_x(base, M, w_acc.x);
        store_y(base, M, w_acc.y);
        store_z(base, w_acc.z);
    }
}
`;

export const ba_reduce_gather_canonical = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

{{> field8_funcs }}

// Gather + Montgomery-strip for the GPU/CPU split. The CPU finishes the reduce
// tail over a small, data-independent working set; this kernel packs exactly
// that set out of red_buf into a dense buffer in the CPU's wire format (LE,
// canonical / NOT Montgomery), so the readback is tiny and the host does no
// field conversion. Thread k copies red_buf[gather_idx[k]] -> dense_out[k],
// stripping the GPU's Montgomery R with one montmul by the canonical integer 1
// (x_mont * 1 * R^-1 = x). Empty slots (is_present == 0) become (0, 0), the
// CPU/marshalling encoding of the point at infinity.

const PG: u32 = 2u;
const WG: u32 = {{ workgroup_size }}u;

@group(0) @binding(0) var<storage, read> red_buf:    array<vec4<u32>>;
@group(0) @binding(1) var<storage, read> is_present: array<u32>;
@group(0) @binding(2) var<storage, read> gather_idx: array<u32>;
@group(0) @binding(3) var<storage, read_write> dense_out: array<vec4<u32>>;
@group(0) @binding(4) var<uniform>       cparams:    vec4<u32>; // (M, k_total, _, _)

fn load_x(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn load_y(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * M + PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let M = cparams.x;
    let k_total = cparams.y;
    let k = gid.x;
    if (k >= k_total) { return; }
    let slot = gather_idx[k];
    let one = array<u32, 8>(1u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
    let present = is_present[slot] != 0u;
    var x: array<u32, 8> = montgomery_product_f8(load_x(slot, M), one);
    var y: array<u32, 8> = montgomery_product_f8(load_y(slot, M), one);
    if (!present) {
        x = array<u32, 8>(0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
        y = array<u32, 8>(0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
    }
    let b = 4u * k; // 4 vec4 = 64 bytes per dense slot (x[8] || y[8])
    dense_out[b + 0u] = vec4<u32>(x[0], x[1], x[2], x[3]);
    dense_out[b + 1u] = vec4<u32>(x[4], x[5], x[6], x[7]);
    dense_out[b + 2u] = vec4<u32>(y[0], y[1], y[2], y[3]);
    dense_out[b + 3u] = vec4<u32>(y[4], y[5], y[6], y[7]);
}
`;

export const ba_reduce_init_bench = `// Reduction-stage init: repack the bucket-accumulate output into the
// reduction's working buffer, and seed the present-mask.
//
// bucket_result has BW columns per window; the weighted buckets are the
// digit magnitudes 1..2^(c-1) — column 0 is the zero digit (weight 0) and
// is dropped, columns past 2^(c-1) are padding and are dropped. red_buf is
// laid out with STRIDE = 2^(c-1) columns per window (a power of two — what
// the 4-phase reduction requires). One thread per red_buf element: copy
// the matching bucket_result element and set is_present iff it is
// non-zero (an empty bucket's accumulate output stays all-zero).

const PG: u32 = 2u;

@group(0) @binding(0) var<storage, read>       bucket_result: array<vec4<u32>>;
@group(0) @binding(1) var<storage, read_write> red_buf:       array<vec4<u32>>;
@group(0) @binding(2) var<storage, read_write> is_present:    array<u32>;
@group(0) @binding(3) var<uniform>             params:        vec4<u32>;
// params.x = total   (NUM_WINDOWS * STRIDE — red_buf element count)
// params.y = STRIDE  (red_buf columns per window)
// params.z = BW      (bucket_result columns per window)
// params.w = B_TOTAL (bucket_result element stride = NUM_WINDOWS * BW)

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let g = gid.x;
    let total = params.x;
    if (g >= total) {
        return;
    }
    let stride = params.y;
    let bw = params.z;
    let b_total = params.w;

    let w = g / stride;
    let i = g % stride;
    // red_buf slot i  <-  bucket_result weighted column (i + 1).
    let src = w * bw + i + 1u;

    let src_x = PG * src;
    let src_y = PG * b_total + PG * src;
    let dst_x = PG * g;
    let dst_y = PG * total + PG * g;

    let x0 = bucket_result[src_x + 0u];
    let x1 = bucket_result[src_x + 1u];
    let y0 = bucket_result[src_y + 0u];
    let y1 = bucket_result[src_y + 1u];

    red_buf[dst_x + 0u] = x0;
    red_buf[dst_x + 1u] = x1;
    red_buf[dst_y + 0u] = y0;
    red_buf[dst_y + 1u] = y1;

    let nz = x0.x | x0.y | x0.z | x0.w | x1.x | x1.y | x1.z | x1.w
           | y0.x | y0.y | y0.z | y0.w | y1.x | y1.y | y1.z | y1.w;
    is_present[g] = select(0u, 1u, nz != 0u);

    {{{ recompile }}}
}
`;

export const ba_reduce_jac_finalize = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> inverse_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

{{> field8_funcs }}

// Convert each window's reduced Jacobian sum (slot w*stride) back to affine
// (x, y) = (X/Z^2, Y/Z^3), in place, in Montgomery form — matching what the
// affine reduce kernel leaves at that slot so the existing per-window gather
// is unchanged. One inversion per window (num_windows total, ~20). Empty
// window (Z == 0) writes the (0, 0) infinity sentinel the host combine
// expects.

const PG: u32 = 2u;
const WG: u32 = {{ workgroup_size }}u;

@group(0) @binding(0) var<storage, read_write> red_buf: array<vec4<u32>>;
@group(0) @binding(1) var<storage, read>       red_z:   array<vec4<u32>>;
@group(0) @binding(2) var<uniform>             cparams: vec4<u32>; // (M, _, stride, num_windows)

fn load_x(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn load_y(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * M + PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn load_z(idx: u32) -> array<u32, 8> {
    let base = PG * idx;
    let q0 = red_z[base + 0u];
    let q1 = red_z[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn store_x(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}
fn store_y(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * M + PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let w = gid.x;
    let M = cparams.x;
    let stride = cparams.z;
    let num_windows = cparams.w;
    if (w >= num_windows) { return; }
    let slot = w * stride;

    let Z = load_z(slot);
    if (is_zero_f8(Z)) {
        let zero = array<u32, 8>(0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
        store_x(slot, M, zero);
        store_y(slot, M, zero);
        return;
    }
    let X = load_x(slot, M);
    let Y = load_y(slot, M);

    // Zinv = (1/Z)~ : same expand -> safegcd -> contract path the affine
    // kernel uses; Montgomery-in / Montgomery-out.
    var z20: BigInt = unpack256_to_limbs(Z);
    var zinv20: BigInt = {{ inv_fn }}(z20);
    var Zinv: array<u32, 8> = pack_limbs_to_256(&zinv20);

    let Z2inv = montgomery_product_f8(Zinv, Zinv);
    let Z3inv = montgomery_product_f8(Z2inv, Zinv);
    let x = montgomery_product_f8(X, Z2inv);
    let y = montgomery_product_f8(Y, Z3inv);
    store_x(slot, M, x);
    store_y(slot, M, y);
}
`;

export const ba_reduce_jac_to_affine = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> inverse_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

{{> field8_funcs }}

// Mid-schedule Jacobian -> affine convert of ALL live slots, batched. Used at a
// jac->affine boundary in the per-level reduction cut: the levels that ran
// Jacobian (red_z plane, Z==0 = infinity) must be normalised back to affine
// (x = X/Z^2, y = Y/Z^3, in red_buf) and have is_present restored before the
// next batch-affine level reads them.
//
// The whole point is to amortise the inversion: each thread takes a chunk of C
// slots, forms the forward prefix-product of their Z's (substituting R for
// Z==0 so infinities don't poison the product), does ONE safegcd inversion,
// then backward-peels the C individual 1/Z. So C slots cost 1 safegcd, not C.
// C is set by the host (cparams.z); larger C => fewer safegcds (but more serial
// prefix work / fewer threads). The prefix lives in conv_scratch (storage, one
// field element per slot) so C is not bounded by the private-array budget.

const PG: u32 = 2u;
const WG: u32 = {{ workgroup_size }}u;

@group(0) @binding(0) var<storage, read_write> red_buf:      array<vec4<u32>>;
@group(0) @binding(1) var<storage, read>       red_z:        array<vec4<u32>>;
@group(0) @binding(2) var<storage, read_write> is_present:   array<u32>;
@group(0) @binding(3) var<storage, read_write> conv_scratch: array<vec4<u32>>;
@group(0) @binding(4) var<uniform>             cparams:      vec4<u32>; // (M, total_slots, chunk_C, nthreads)

fn load_x(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn load_y(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * M + PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn load_z(idx: u32) -> array<u32, 8> {
    let base = PG * idx;
    let q0 = red_z[base + 0u];
    let q1 = red_z[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn store_x(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}
fn store_y(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * M + PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}
fn store_pref(slot: u32, val: array<u32, 8>) {
    let base = PG * slot;
    conv_scratch[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    conv_scratch[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}
fn load_pref(slot: u32) -> array<u32, 8> {
    let base = PG * slot;
    let q0 = conv_scratch[base + 0u];
    let q1 = conv_scratch[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
fn fr_select_f8(a: array<u32, 8>, b: array<u32, 8>, cond: bool) -> array<u32, 8> {
    return array<u32, 8>(
        select(a[0], b[0], cond), select(a[1], b[1], cond),
        select(a[2], b[2], cond), select(a[3], b[3], cond),
        select(a[4], b[4], cond), select(a[5], b[5], cond),
        select(a[6], b[6], cond), select(a[7], b[7], cond));
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let M = cparams.x;
    let total = cparams.y;
    let C = cparams.z;
    let nthreads = cparams.w;
    let tid = gid.x;
    if (tid >= nthreads) { return; }
    let R: array<u32, 8> = get_r_f8();
    let zero = array<u32, 8>(0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);

    // ---- forward: prefix product of the chunk's (infinity-substituted) Z ----
    var acc: array<u32, 8> = R;
    for (var k: u32 = 0u; k < C; k = k + 1u) {
        let slot = tid * C + k;
        var z: array<u32, 8> = R;
        if (slot < total) {
            let Z = load_z(slot);
            z = fr_select_f8(Z, R, is_zero_f8(Z));
        }
        acc = montgomery_product_f8(acc, z);
        if (slot < total) { store_pref(slot, acc); }
    }

    // ---- single inversion of the whole chunk's product ----
    var acc20: BigInt = unpack256_to_limbs(acc);
    var inv20: BigInt = {{ inv_fn }}(acc20);
    var inv: array<u32, 8> = pack_limbs_to_256(&inv20);

    // ---- backward peel: recover each 1/Z, convert in place ----
    for (var kk: u32 = 0u; kk < C; kk = kk + 1u) {
        let k = C - 1u - kk;
        let slot = tid * C + k;
        if (slot >= total) { continue; }
        let Z = load_z(slot);
        let isinf = is_zero_f8(Z);
        let zsub = fr_select_f8(Z, R, isinf);
        let prev_slot = select(slot - 1u, 0u, k == 0u);
        let pp = fr_select_f8(load_pref(prev_slot), R, k == 0u);
        let zinv = montgomery_product_f8(inv, pp); // 1/zsub for this slot
        inv = montgomery_product_f8(inv, zsub);

        let X = load_x(slot, M);
        let Y = load_y(slot, M);
        let Z2inv = montgomery_product_f8(zinv, zinv);
        let Z3inv = montgomery_product_f8(Z2inv, zinv);
        let x = montgomery_product_f8(X, Z2inv);
        let y = montgomery_product_f8(Y, Z3inv);
        store_x(slot, M, fr_select_f8(x, zero, isinf));
        store_y(slot, M, fr_select_f8(y, zero, isinf));
        is_present[slot] = select(1u, 0u, isinf);
    }
}
`;

export const ba_reduce_level_bench = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> inverse_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

{{> field8_funcs }}

// One level of the recursive affine bucket reduction. The host issues one
// dispatch per schedule level; WebGPU's between-pass ordering provides the
// cross-level memory ordering. ALL THREE kinds (phase-A suffix add,
// phase-B/D tree-add, phase-C double) share this single kernel and select
// behaviour via \`lparams.w\` — uniform across the workgroup, so the compiler
// specialises per-dispatch with zero SIMT divergence cost. Phase 5 of
// UNIFIED_COMBINE_PLAN.md collapses three kind-specialised pipelines into
// one.
//
// Branchless within a thread: every data-dependent decision (bucket
// presence, the add-vs-copy-vs-skip cases, the per-candidate denominator)
// is a \`select\`, not an \`if\`. Point-equality (P = +/-Q) handling is
// omitted — the algorithm assumes uniformly-random inputs with no point
// collisions, so the affine add denominator x_s - x_d is never zero.
//
// One workgroup per window. Field elements are 8x u32 (Lever 2); see
// field8_funcs.

const PG: u32 = 2u;
const WG: u32 = {{ workgroup_size }}u;
const KIND_SUFFIX:  u32 = 0u;   // dst += src,  dst = src - 1
const KIND_TREE:    u32 = 1u;   // dst += src,  dst = 2*j2*pa, src = (2*j2+1)*pa
const KIND_DOUBLE:  u32 = 2u;   // slot = 2*slot, slot = base + (j2+1)*pa

@group(0) @binding(0) var<storage, read_write> red_buf:      array<vec4<u32>>;
@group(0) @binding(1) var<storage, read_write> is_present:   array<u32>;
@group(0) @binding(2) var<storage, read_write> pref_scratch: array<vec4<u32>>;
@group(0) @binding(3) var<uniform>             cparams:      vec4<u32>;
@group(0) @binding(4) var<uniform>             lparams:      vec4<u32>;
// cparams = (M (red_buf element stride), maxc (pref slots/thread), STRIDE, _)
//   — constant across all levels.
// lparams = (pa, pb, ppw, kind) — this level's flattened schedule entry.

fn load_x(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

fn load_y(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * M + PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

fn store_x(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn store_y(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * M + PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn store_pref(slot: u32, val: array<u32, 8>) {
    let base = 2u * slot;
    pref_scratch[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    pref_scratch[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn load_pref(slot: u32) -> array<u32, 8> {
    let base = 2u * slot;
    let q0 = pref_scratch[base + 0u];
    let q1 = pref_scratch[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

// Branchless elementwise select on the 8x u32 field form: returns \`b\` when
// \`cond\`, else \`a\` (matches WGSL's select(false_val, true_val, cond)).
fn fr_select_f8(a: array<u32, 8>, b: array<u32, 8>, cond: bool) -> array<u32, 8> {
    return array<u32, 8>(
        select(a[0], b[0], cond), select(a[1], b[1], cond),
        select(a[2], b[2], cond), select(a[3], b[3], cond),
        select(a[4], b[4], cond), select(a[5], b[5], cond),
        select(a[6], b[6], cond), select(a[7], b[7], cond));
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(workgroup_id) wgid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
    let w = wgid.x;       // window — one workgroup per window
    let tid = lid.x;      // thread within the workgroup
    let M = cparams.x;
    let maxc = cparams.y;
    let stride = cparams.z;
    let pa = lparams.x;
    let pb = lparams.y;
    let ppw = lparams.z;
    let kind = lparams.w;
    let base = w * stride;
    let scratch_base = (w * WG + tid) * maxc;
    // Candidates per thread this level — uniform across the workgroup.
    let C = (ppw + WG - 1u) / WG;

    if (tid * C >= ppw) {
        return;
    }
    let R: array<u32, 8> = get_r_f8();

    // ---- forward: prefix product of per-candidate denominators ----
    var acc: array<u32, 8> = R;
    for (var k: u32 = 0u; k < C; k = k + 1u) {
        let j2 = tid * C + k;
        let in_range = j2 < ppw;

        var real_denom: array<u32, 8>;
        var present: bool;
        if (kind == KIND_DOUBLE) {
            let slot = base + (j2 + 1u) * pa;
            present = in_range && (is_present[slot] != 0u);
            let yv = load_y(slot, M);
            real_denom = fr_add_f8(yv, yv); // 2y
        } else {
            var src: u32;
            var dst: u32;
            if (kind == KIND_SUFFIX) {
                src = base + j2 * pa + pb;
                dst = src - 1u;
            } else {
                // KIND_TREE
                dst = base + 2u * j2 * pa;
                src = base + (2u * j2 + 1u) * pa;
            }
            present = in_range && (is_present[src] != 0u) && (is_present[dst] != 0u);
            let x_s = load_x(src, M);
            let x_d = load_x(dst, M);
            real_denom = fr_sub_f8(x_s, x_d); // x_s - x_d (nonzero: no collisions)
        }
        let denom: array<u32, 8> = fr_select_f8(R, real_denom, present);
        acc = montgomery_product_f8(acc, denom);
        store_pref(scratch_base + k, acc);
    }

    // Single inversion per chunk.
    var acc20: BigInt = unpack256_to_limbs(acc);
    var inv20: BigInt = {{ inv_fn }}(acc20);
    var inv: array<u32, 8> = pack_limbs_to_256(&inv20);

    // ---- backward peel ----
    for (var kk: u32 = 0u; kk < C; kk = kk + 1u) {
        let k = C - 1u - kk;
        let j2 = tid * C + k;
        let in_range = j2 < ppw;
        let km1 = max(k, 1u) - 1u;
        let pp: array<u32, 8> = fr_select_f8(load_pref(scratch_base + km1), R, k == 0u);
        let inv_denom: array<u32, 8> = montgomery_product_f8(inv, pp);

        if (kind == KIND_DOUBLE) {
            let slot = base + (j2 + 1u) * pa;
            let present = in_range && (is_present[slot] != 0u);
            let xv: array<u32, 8> = load_x(slot, M);
            let yv: array<u32, 8> = load_y(slot, M);
            let real_denom: array<u32, 8> = fr_add_f8(yv, yv); // 2y
            let x2: array<u32, 8> = montgomery_product_f8(xv, xv);
            var num: array<u32, 8> = fr_add_f8(x2, x2);
            num = fr_add_f8(num, x2); // 3x^2
            let lambda: array<u32, 8> = montgomery_product_f8(num, inv_denom);
            let two_x: array<u32, 8> = fr_add_f8(xv, xv);
            var r_x: array<u32, 8> = montgomery_product_f8(lambda, lambda);
            r_x = fr_sub_f8(r_x, two_x);
            var r_y: array<u32, 8> = fr_sub_f8(xv, r_x);
            r_y = montgomery_product_f8(lambda, r_y);
            r_y = fr_sub_f8(r_y, yv);
            let out_x: array<u32, 8> = fr_select_f8(xv, r_x, present);
            let out_y: array<u32, 8> = fr_select_f8(yv, r_y, present);
            let denom_k: array<u32, 8> = fr_select_f8(R, real_denom, present);
            inv = montgomery_product_f8(inv, denom_k);
            if (in_range) {
                store_x(slot, M, out_x);
                store_y(slot, M, out_y);
            }
        } else {
            var src: u32;
            var dst: u32;
            if (kind == KIND_SUFFIX) {
                src = base + j2 * pa + pb;
                dst = src - 1u;
            } else {
                dst = base + 2u * j2 * pa;
                src = base + (2u * j2 + 1u) * pa;
            }
            let ps = is_present[src] != 0u;
            let pl = is_present[dst] != 0u;
            let both = in_range && ps && pl;       // dst += src (affine add)
            let copy = in_range && ps && (!pl);    // dst = src (occupy empty slot)
            let x_d: array<u32, 8> = load_x(dst, M);
            let x_s: array<u32, 8> = load_x(src, M);
            let y_d: array<u32, 8> = load_y(dst, M);
            let y_s: array<u32, 8> = load_y(src, M);
            let dx: array<u32, 8> = fr_sub_f8(x_s, x_d);
            var lambda: array<u32, 8> = fr_sub_f8(y_s, y_d);
            lambda = montgomery_product_f8(lambda, inv_denom);
            var add_rx: array<u32, 8> = montgomery_product_f8(lambda, lambda);
            let x_sum: array<u32, 8> = fr_add_f8(x_d, x_s);
            add_rx = fr_sub_f8(add_rx, x_sum);
            var add_ry: array<u32, 8> = fr_sub_f8(x_d, add_rx);
            add_ry = montgomery_product_f8(lambda, add_ry);
            add_ry = fr_sub_f8(add_ry, y_d);
            var out_x: array<u32, 8> = fr_select_f8(x_d, x_s, copy);
            out_x = fr_select_f8(out_x, add_rx, both);
            var out_y: array<u32, 8> = fr_select_f8(y_d, y_s, copy);
            out_y = fr_select_f8(out_y, add_ry, both);
            let denom_k: array<u32, 8> = fr_select_f8(R, dx, both);
            inv = montgomery_product_f8(inv, denom_k);
            let new_present: u32 = select(u32(pl), 1u, copy);
            if (in_range) {
                store_x(dst, M, out_x);
                store_y(dst, M, out_y);
                is_present[dst] = new_present;
            }
        }
    }

    {{{ recompile }}}
}
`;

